import{_ as e,o,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"1. 背景回顾：为什么会“漏刷”","description":"flushAll 在一次 requestAnimationFrame （rAF）回调内遍历 priceQueue ，对 多个 symbol 连续赋值同一个响应式字段 newQuotePayload ： this.newQuotePayload \\\\{ symbol, quote:。","frontmatter":{"title":"1. 背景回顾：为什么会“漏刷”","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"flushAll 在一次 requestAnimationFrame （rAF）回调内遍历 priceQueue ，对 多个 symbol 连续赋值同一个响应式字段 newQuotePayload ： this.newQuotePayload \\\\{ symbol, quote:。","sidebarWeight":131,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/1. 背景回顾：为什么会“漏刷”.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/1. 背景回顾：为什么会“漏刷”.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/1. 背景回顾：为什么会“漏刷”.md"}'),l={name:"posts/Vue系统教程/03-响应式与组合式 API/1. 背景回顾：为什么会“漏刷”.md"};function s(i,t,d,n,u,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<div><h1 id="_1-背景回顾-为什么会-漏刷" tabindex="-1">1. 背景回顾：为什么会“漏刷” <a class="header-anchor" href="#_1-背景回顾-为什么会-漏刷" aria-label="Permalink to &quot;1. 背景回顾：为什么会“漏刷”&quot;">​</a></h1><blockquote><p>本节目标：理解“1. 背景回顾：为什么会“漏刷””的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <code>flushAll</code> 在一次 <code>requestAnimationFrame</code>（rAF）回调内遍历 <code>priceQueue</code>，对 <strong>多个 symbol</strong> 连续赋值同一个响应式字段 <code>newQuotePayload</code>： this.newQuotePayload = { symbol, quote: last };</p></blockquote><p>Vue 为了性能会把同一<strong>宏任务</strong>（macrotask）里对同一响应式字段的多次写入合并，只触发最后一次 watch；</p><p>于是同帧内除了最后一个 symbol 之外，其余的报价都被“覆盖”了，界面得不到更新。</p><ol start="2"><li>解决思路</li><li>本帧内先把每个 symbol 的最新报价收集到 <code>batch</code>。</li><li>再把 <strong>每条报价各自推入微任务队列（microtask queue）</strong>。</li></ol><ul><li>这样就把一次宏任务拆成了 N 次相邻微任务。</li><li>Vue 的 watch 会在每个微任务结尾执行，因此 <strong>每个 symbol 都能独立触发一次 watch</strong>。</li></ul><p>对应改动（节选） // 收集 batch.push({ symbol, quote: last }); // 派发 batch.forEach(({ symbol, quote }) =&gt; { const dispatch = () =&gt; { this.newQuotePayload = { symbol, quote } as any; }; if (typeof queueMicrotask === &#39;function&#39;) { queueMicrotask(dispatch); // 推荐 } else { Promise.resolve().then(dispatch); // 回退 } }); 3. 事件循环（Event Loop）全景</p><p>浏览器的执行模型可以抽象成<strong>事件循环 → 渲染循环</strong>的交替：</p><ol><li><strong>取出一个宏任务</strong>（macrotask）执行。</li><li><strong>Microtask Check-point</strong>：不断取出并执行所有微任务，直到清空。</li></ol><ul><li>期间如果又加入了新的微任务（例如 then 里再 then），也会立刻继续执行。</li></ul><ol start="3"><li>执行 <strong>render 阶段</strong>：</li></ol><ul><li>浏览器更新样式计算(Layout)、绘制(Paint)、合成(Composite)。</li><li>此阶段会调用 rAF 回调，为下一帧 JavaScript 预留入口。</li></ul><ol start="4"><li><p>返回步骤 1，进入下一轮循环。</p></li><li><p>queueMicrotask — 微任务的“官方”入口</p></li></ol><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>特性</td><td>说明</td></tr><tr><td>规范</td><td>WHATWG HTML Standard，现代浏览器均支持（Chrome 71+，Edge 79+，Firefox 69+，Safari 13+）。</td></tr><tr><td>作用</td><td>将回调排进 当前宏任务结束前 必执行的微任务队列。</td></tr><tr><td>与 Promise.then 区别</td><td>&lt;br&gt;• API 直接、语义更清晰；&lt;br&gt;• 不涉及生成冗余的 Promise 对象；&lt;br&gt;• 部分环境（老 Node）里不依赖原生 Promise 也可用。</td></tr><tr><td>与 setTimeout 区别</td><td>setTimeout 属于 宏任务，至少延后到下一轮事件循环；queueMicrotask 属于 微任务，本轮必执行且早于渲染。</td></tr></tbody></table><p>用法 queueMicrotask(() =&gt; { // 在当前宏任务结束、渲染之前执行 }); 浏览器不支持时，可退化成 <code>Promise.resolve().then(...)</code>，效果等同。</p><ol start="5"><li>requestAnimationFrame 与渲染时序 ┌ 上一帧渲染完毕 │ ├─(1) 调用 rAF 回调 ← 这里我们执行 flushAll() │ ├─(2) 执行 microtask queue ← 我们新建的 queueMicrotask 在此阶段运行 │ └─(3) 浏览器进行下一次渲染</li></ol><p>因此我们的修改保证：</p><ol><li><strong>同一帧</strong>：所有 symbol 的报价都能通过各自的微任务触发 Vue watcher。</li><li><strong>渲染前</strong>：UI 已经完成数据 diff，DOM patch，达到一致性。</li><li><strong>下一帧</strong>：浏览器把补丁一次性绘制，避免多次布局/重绘。</li></ol><h1 id="_6-vue3-reactivity-watch-的调度细节" tabindex="-1">6. Vue3 Reactivity + Watch 的调度细节 <a class="header-anchor" href="#_6-vue3-reactivity-watch-的调度细节" aria-label="Permalink to &quot;6. Vue3 Reactivity + Watch 的调度细节&quot;">​</a></h1><ul><li>Vue 自己也会把响应式副作用包装进微任务，等本轮 flush 一起触发。</li><li>如果你在<strong>同一个微任务</strong>里多次写入同一 ref/prop，Vue 会合并，只触发一次 watcher。</li><li>将写入拆到<strong>不同的微任务</strong>——即我们现在的做法——则每次都会触发一次独立的副作用更新。</li></ul><h1 id="_7-方案优缺点" tabindex="-1">7. 方案优缺点 <a class="header-anchor" href="#_7-方案优缺点" aria-label="Permalink to &quot;7. 方案优缺点&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>方案</td><td>优点</td><td>缺点</td></tr><tr><td>微任务拆分（现方案）</td><td>• 改动极小；&lt;br&gt;• watch 代码几乎不用动；&lt;br&gt;• 不改变数据结构</td><td>• 对极大量 symbol 每帧都拆分微任务时，可能带来微任务风暴（一般行情推送频率较低，影响可忽略）。</td></tr><tr><td>把 newQuotePayload 改成 Map/Array</td><td>• 一帧一次 watch；更易做批处理</td><td>• 需要改动所有 watch 端（OpenOrder、PendingOrder、行情表格等）；&lt;br&gt;• Watch 逻辑要做遍历与过滤，代码量更大。</td></tr><tr><td>rAF 多帧轮询</td><td>• 实现简单</td><td>• 若 symbol 很多，会拖长整体刷新延迟；体验不佳。</td></tr></tbody></table></div>',1)])])}const m=e(l,[["render",s]]);export{p as __pageData,m as default};
